"""Runtime support for code generated by Oxychloride (https://github.com/palladio/oxychloride).

This module is copied verbatim into every generated Python package; it needs nothing but
the standard library (Python 3.9 or later). It provides

* ``EObject``, the base class of the generated classes, and the descriptors
  ``Attribute`` and ``Reference`` that keep containment and bidirectional references
  consistent (like EMF does);
* ``Resource``, ``load``/``loads``/``save``/``dumps``: XMI documents;
* ``validate``: multiplicities and OCL invariants, as ``Diagnostic`` objects;
* the OCL standard library operations the generated code calls (``OclInvalid`` is raised
  where OCL evaluates to ``invalid``);
* pre- and postcondition checking (``ContractViolation``, ``set_contract_checking``).

Do not edit: it is overwritten when the code is generated again.
"""

from __future__ import annotations

import enum as _enum
import math
import re
from typing import Any, Callable, Iterable, Iterator, List, Optional
import xml.etree.ElementTree as ET

__all__ = [
    "EObject",
    "Enum",
    "Resource",
    "Diagnostic",
    "OclInvalid",
    "ContractViolation",
    "load",
    "loads",
    "save",
    "dumps",
    "validate",
    "set_contract_checking",
]

XMI_NS = "http://www.omg.org/XMI"
XSI_NS = "http://www.w3.org/2001/XMLSchema-instance"


# ---------------------------------------------------------------------------- errors


class OclInvalid(Exception):
    """An OCL expression evaluated to ``invalid`` (null navigation, index out of range, …)."""


class ContractViolation(Exception):
    """A pre- or postcondition of an operation does not hold (or could not be evaluated)."""

    def __init__(self, kind: str, operation: str, constraint: str, obj: Any, message: Optional[str], status: str):
        self.kind = kind
        self.operation = operation
        self.constraint = constraint
        self.object = obj
        self.message = message
        self.status = status
        what = f"{kind} {constraint} of {operation}"
        detail = f": {message}" if message else ""
        super().__init__(f"{what} {'is violated' if status == 'violated' else 'failed'} on {label(obj)}{detail}")


def invalid(reason: str) -> Any:
    """Raises ``OclInvalid``: the translation of OCL's ``invalid``."""
    raise OclInvalid(reason)


_check_contracts = True


def set_contract_checking(enabled: bool) -> None:
    """Turns checking pre- and postconditions at operation calls on or off (on by default)."""
    global _check_contracts
    _check_contracts = enabled


def contracts_enabled() -> bool:
    return _check_contracts


def check_condition(kind: str, obj: Any, operation: str, name: str, condition: Callable[[], Any],
                    message: Optional[Callable[[], Any]] = None) -> None:
    """Evaluates a pre- or postcondition; raises ``ContractViolation`` unless it is true."""
    try:
        value = condition()
    except Exception as e:  # noqa: BLE001 - any failure makes the condition invalid
        raise ContractViolation(kind, operation, name, obj, str(e) or type(e).__name__, "error") from e
    if value is True:
        return
    status = "violated" if value is False else "error"
    text = None
    if message is not None and status == "violated":
        try:
            text = to_string(message())
        except Exception:  # noqa: BLE001
            text = None
    if status == "error":
        text = f"evaluated to {to_string(value)}"
    raise ContractViolation(kind, operation, name, obj, text, status)


# ---------------------------------------------------------------------------- metadata


_packages: dict = {}


class Package:
    """An EPackage: its name, namespace and classes (filled by the generated module)."""

    def __init__(self, name: str, ns_uri: str, ns_prefix: str):
        self.name = name
        self.ns_uri = ns_uri
        self.ns_prefix = ns_prefix
        self.classifiers: dict = {}
        if ns_uri:
            _packages[ns_uri] = self

    def register(self, classifier: Any) -> Any:
        self.classifiers[classifier._e_name] = classifier
        return classifier

    def __repr__(self) -> str:
        return f"Package({self.name!r}, {self.ns_uri!r})"


class Enum(_enum.Enum):
    """Base class of generated enumerations: literals are ordered as declared and have the
    serialized form ``literal``."""

    @property
    def literal(self) -> str:
        return type(self)._literals_.get(self.name, self.name)

    def _index(self) -> int:
        return list(type(self)).index(self)

    def __lt__(self, other: Any) -> bool:
        if type(other) is not type(self):
            return NotImplemented
        return self._index() < other._index()

    def __le__(self, other: Any) -> bool:
        if type(other) is not type(self):
            return NotImplemented
        return self._index() <= other._index()

    def __gt__(self, other: Any) -> bool:
        if type(other) is not type(self):
            return NotImplemented
        return self._index() > other._index()

    def __ge__(self, other: Any) -> bool:
        if type(other) is not type(self):
            return NotImplemented
        return self._index() >= other._index()

    def __str__(self) -> str:
        return f"{type(self).__name__}::{self.name}"

    @classmethod
    def from_literal(cls, text: str) -> "Enum":
        for member in cls:
            if member.literal == text or member.name == text:
                return member
        raise ValueError(f"{text!r} is not a literal of {cls.__name__}")


_UNSET = object()


class Feature:
    """A structural feature of a generated class (a Python descriptor).

    ``kind`` is the value kind: ``"boolean"``, ``"integer"``, ``"real"``, ``"string"``,
    ``"enum"``, ``"datatype"`` (strings) or ``"object"``. ``type`` returns the enumeration or
    class of the values (it is a function, so classes may refer to each other).
    """

    is_reference = False

    def __init__(self, name: str, kind: str, type: Optional[Callable[[], Any]] = None, *, many: bool = False,
                 lower: int = 0, upper: int = 1, ordered: bool = True, unique: bool = True, default: Any = None,
                 changeable: bool = True, serialized: bool = True, id: bool = False,
                 initial: Optional[Callable[[Any], Any]] = None):
        self.name = name
        self.kind = kind
        self._type = type
        self.many = many
        self.lower = lower
        self.upper = upper
        self.ordered = ordered
        self.unique = unique
        self.default = default
        self.changeable = changeable
        self.serialized = serialized
        self.id = id
        self.initial = initial
        self.attr = name
        self.owner: Any = None

    def __set_name__(self, owner: Any, attr: str) -> None:
        self.attr = attr
        self.owner = owner

    @property
    def type(self) -> Any:
        return self._type() if self._type is not None else None

    containment = False
    container = False
    opposite: Optional[str] = None

    def opposite_feature(self) -> Optional["Feature"]:
        return None

    def __get__(self, obj: Any, objtype: Any = None) -> Any:
        if obj is None:
            return self
        value = obj._e_values.get(self.name, _UNSET)
        if value is _UNSET:
            if self.many:
                value = EList(obj, self)
                obj._e_values[self.name] = value
                return value
            value = self.default
        if value is None and self.initial is not None:
            return self.initial(obj)
        return value

    def __set__(self, obj: Any, value: Any) -> None:
        if self.many:
            items = self.__get__(obj)
            items.clear()
            items.extend(value)
            return
        obj._e_values[self.name] = value

    def is_set(self, obj: Any) -> bool:
        value = obj._e_values.get(self.name, _UNSET)
        if self.many:
            return value is not _UNSET and len(value) > 0
        return value is not _UNSET and value is not None and value != self.default

    def __repr__(self) -> str:
        return f"<feature {self.owner.__name__ if self.owner else '?'}.{self.name}>"


class Attribute(Feature):
    """An attribute (``EAttribute``)."""


class Reference(Feature):
    """A reference (``EReference``): containment and opposites are kept consistent."""

    is_reference = True

    def __init__(self, name: str, type: Callable[[], Any], *, containment: bool = False, container: bool = False,
                 opposite: Optional[str] = None, **kwargs: Any):
        super().__init__(name, "object", type, **kwargs)
        self.containment = containment
        self.container = container
        self.opposite = opposite

    def opposite_feature(self) -> Optional[Feature]:
        if self.opposite is None:
            return None
        return self.type._e_feature(self.opposite)

    def __get__(self, obj: Any, objtype: Any = None) -> Any:
        if obj is None:
            return self
        if self.container:
            container = obj._e_container
            if container is not None and obj._e_containing_feature is self.opposite_feature():
                return container
            return None
        return super().__get__(obj, objtype)

    def __set__(self, obj: Any, value: Any) -> None:
        if self.many:
            items = self.__get__(obj)
            items.clear()
            items.extend(value)
            return
        if self.container:
            opposite = self.opposite_feature()
            if value is None:
                if obj._e_container is not None and obj._e_containing_feature is opposite:
                    _remove_from(obj._e_container, opposite, obj)
            else:
                _add_to(value, opposite, obj)
            return
        old = obj._e_values.get(self.name)
        if old is value:
            return
        obj._e_values[self.name] = value
        if self.containment:
            if old is not None:
                _detach(old)
            if value is not None:
                _attach(value, obj, self)
        opposite = self.opposite_feature()
        if opposite is not None and not self.containment:
            if old is not None:
                _basic_remove(old, opposite, obj)
            if value is not None:
                _inverse_add(value, opposite, obj)


def _check_type(feature: Feature, value: Any) -> None:
    if feature.is_reference and not isinstance(value, feature.type):
        raise TypeError(f"{feature.owner.__name__}.{feature.attr} expects {feature.type.__name__}, "
                        f"not {type(value).__name__}")


def _attach(child: Any, container: Any, feature: Feature) -> None:
    """Makes ``container`` the container of ``child`` (removing it from its old one)."""
    if child._e_container is not None and (child._e_container is not container or child._e_containing_feature is not feature):
        _remove_from(child._e_container, child._e_containing_feature, child)
    if child._e_resource is not None:
        child._e_resource.contents._basic_remove(child)
    child._e_container = container
    child._e_containing_feature = feature


def _detach(child: Any) -> None:
    child._e_container = None
    child._e_containing_feature = None


def _basic_remove(obj: Any, feature: Feature, value: Any) -> None:
    """Removes ``value`` from ``obj.feature`` without touching the opposite."""
    if feature.many:
        items = feature.__get__(obj)
        if value in items._items:
            items._items.remove(value)
    elif obj._e_values.get(feature.name) is value:
        obj._e_values[feature.name] = None


def _inverse_add(obj: Any, feature: Feature, value: Any) -> None:
    """Adds ``value`` to ``obj.feature`` as the opposite side of a link."""
    if feature.many:
        items = feature.__get__(obj)
        if value not in items._items:
            items._items.append(value)
    else:
        old = obj._e_values.get(feature.name)
        if old is value:
            return
        obj._e_values[feature.name] = value
        if old is not None:
            # ``old`` loses ``obj`` on the other side.
            _basic_remove(old, feature.opposite_feature(), obj)


def _add_to(obj: Any, feature: Feature, value: Any) -> None:
    if feature.many:
        feature.__get__(obj).append(value)
    else:
        feature.__set__(obj, value)


def _remove_from(obj: Any, feature: Feature, value: Any) -> None:
    if feature.many:
        items = feature.__get__(obj)
        if value in items._items:
            items.remove(value)
    elif feature.__get__(obj) is value:
        feature.__set__(obj, None)


class EList:
    """The value of a many-valued feature: a list that keeps containment and opposites
    consistent (adding a book to ``library.books`` sets ``book.library``)."""

    def __init__(self, owner: Any, feature: Feature):
        self._owner = owner
        self._feature = feature
        self._items: list = []

    def _added(self, value: Any) -> None:
        f = self._feature
        if f.containment:
            _attach(value, self._owner, f)
        opposite = f.opposite_feature()
        if opposite is not None and not f.containment:
            _inverse_add(value, opposite, self._owner)

    def _removed(self, value: Any) -> None:
        f = self._feature
        if f.containment:
            _detach(value)
        opposite = f.opposite_feature()
        if opposite is not None and not f.containment:
            _basic_remove(value, opposite, self._owner)

    def insert(self, index: int, value: Any) -> None:
        if value is None:
            raise ValueError(f"{self._feature.attr} cannot contain None")
        _check_type(self._feature, value)
        if self._feature.unique and value in self._items:
            return
        self._items.insert(index, value)
        self._added(value)

    def append(self, value: Any) -> None:
        self.insert(len(self._items), value)

    def extend(self, values: Iterable[Any]) -> None:
        for v in list(values):
            self.append(v)

    def remove(self, value: Any) -> None:
        self._items.remove(value)
        self._removed(value)

    def _basic_remove(self, value: Any) -> None:
        if value in self._items:
            self._items.remove(value)

    def pop(self, index: int = -1) -> Any:
        value = self._items[index]
        self.remove(value)
        return value

    def clear(self) -> None:
        for v in list(self._items):
            self.remove(v)

    def index(self, value: Any) -> int:
        return self._items.index(value)

    def count(self, value: Any) -> int:
        return self._items.count(value)

    def __iter__(self) -> Iterator[Any]:
        return iter(list(self._items))

    def __len__(self) -> int:
        return len(self._items)

    def __getitem__(self, index: Any) -> Any:
        return self._items[index]

    def __contains__(self, value: Any) -> bool:
        return value in self._items

    def __eq__(self, other: Any) -> bool:
        return list(self._items) == list(other)

    def __repr__(self) -> str:
        return repr(self._items)


class EObject:
    """Base class of all generated classes."""

    _e_package: Optional[Package] = None
    _e_name = "EObject"
    _e_abstract = True
    _e_features: tuple = ()
    _e_invariants: tuple = ()

    def __init_subclass__(cls, **kwargs: Any) -> None:
        super().__init_subclass__(**kwargs)
        # All features including inherited ones, inherited first (EMF's order).
        features: list = []
        for klass in reversed(cls.__mro__):
            for value in vars(klass).values():
                if isinstance(value, Feature) and all(f.name != value.name for f in features):
                    features.append(value)
        cls._e_features = tuple(features)

    def __init__(self, **values: Any):
        if type(self)._e_abstract:
            raise TypeError(f"{type(self).__name__} is abstract")
        self._e_values: dict = {}
        self._e_container: Any = None
        self._e_containing_feature: Optional[Feature] = None
        self._e_resource: Optional[Resource] = None
        for name, value in values.items():
            feature = type(self)._e_feature_by_attr(name)
            if feature is None:
                raise TypeError(f"{type(self).__name__} has no feature {name!r}")
            setattr(self, name, value)

    @classmethod
    def _e_feature(cls, name: str) -> Optional[Feature]:
        """The feature with the given (metamodel) name."""
        for f in cls._e_features:
            if f.name == name:
                return f
        return None

    @classmethod
    def _e_feature_by_attr(cls, attr: str) -> Optional[Feature]:
        for f in cls._e_features:
            if f.attr == attr:
                return f
        return None

    @classmethod
    def e_class_name(cls) -> str:
        """The qualified name of the class, e.g. ``library::Book``."""
        package = cls._e_package.name if cls._e_package else "?"
        return f"{package}::{cls._e_name}"

    def e_class(self) -> type:
        return type(self)

    def e_container(self) -> Any:
        """The object containing this one, or None."""
        return self._e_container

    def e_containing_feature(self) -> Optional[Feature]:
        return self._e_containing_feature

    def e_resource(self) -> Optional["Resource"]:
        """The resource of the root container of this object, if it is in one."""
        root = self
        while root._e_container is not None:
            root = root._e_container
        return root._e_resource

    def e_contents(self) -> list:
        """The objects this one contains directly."""
        out: list = []
        for f in type(self)._e_features:
            if f.containment:
                value = f.__get__(self)
                if f.many:
                    out.extend(value)
                elif value is not None:
                    out.append(value)
        return out

    def e_all_contents(self) -> list:
        """The objects this one contains, transitively (depth first)."""
        out: list = []
        for child in self.e_contents():
            out.append(child)
            out.extend(child.e_all_contents())
        return out

    def e_get(self, name: str) -> Any:
        """The value of a feature by its metamodel name."""
        feature = type(self)._e_feature(name)
        if feature is None:
            raise AttributeError(f"{type(self).__name__} has no feature {name!r}")
        return feature.__get__(self)

    def e_set(self, name: str, value: Any) -> None:
        feature = type(self)._e_feature(name)
        if feature is None:
            raise AttributeError(f"{type(self).__name__} has no feature {name!r}")
        feature.__set__(self, value)

    def e_delete(self) -> None:
        """Removes the object from its container and from every reference of the objects
        reachable from its root (like EMF's ``EcoreUtil.delete``)."""
        root = self
        while root._e_container is not None:
            root = root._e_container
        roots = root._e_resource.contents if root._e_resource is not None else [root]
        doomed = {id(self)} | {id(o) for o in self.e_all_contents()}
        for r in list(roots):
            for o in [r, *r.e_all_contents()]:
                if id(o) in doomed:
                    continue
                for f in type(o)._e_features:
                    if not f.is_reference or f.containment or f.container:
                        continue
                    if f.many:
                        for v in list(f.__get__(o)):
                            if id(v) in doomed:
                                f.__get__(o).remove(v)
                    elif id(f.__get__(o) or o) in doomed:
                        f.__set__(o, None)
        if self._e_container is not None:
            _remove_from(self._e_container, self._e_containing_feature, self)
        elif self._e_resource is not None:
            self._e_resource.contents.remove(self)

    def __repr__(self) -> str:
        return f"<{label(self)}>"


def label(obj: Any) -> str:
    """A human readable label such as ``Book 'Dune'``."""
    if not isinstance(obj, EObject):
        return to_string(obj)
    name_feature = type(obj)._e_feature("name")
    name = name_feature.__get__(obj) if name_feature is not None else None
    if isinstance(name, str):
        return f"{type(obj)._e_name} '{name}'"
    return f"{type(obj)._e_name} {uri_fragment(obj)}"


# ---------------------------------------------------------------------------- resources


class _Contents:
    """The root objects of a resource."""

    def __init__(self, resource: "Resource"):
        self._resource = resource
        self._items: list = []

    def append(self, obj: Any) -> None:
        if obj in self._items:
            return
        if obj._e_container is not None:
            _remove_from(obj._e_container, obj._e_containing_feature, obj)
        if obj._e_resource is not None:
            obj._e_resource.contents._basic_remove(obj)
        self._items.append(obj)
        obj._e_resource = self._resource

    def extend(self, objs: Iterable[Any]) -> None:
        for o in list(objs):
            self.append(o)

    def remove(self, obj: Any) -> None:
        self._items.remove(obj)
        obj._e_resource = None

    def _basic_remove(self, obj: Any) -> None:
        if obj in self._items:
            self._items.remove(obj)
        obj._e_resource = None

    def __iter__(self) -> Iterator[Any]:
        return iter(list(self._items))

    def __len__(self) -> int:
        return len(self._items)

    def __getitem__(self, index: Any) -> Any:
        return self._items[index]

    def __contains__(self, obj: Any) -> bool:
        return obj in self._items

    def __repr__(self) -> str:
        return repr(self._items)


class Resource:
    """An XMI document: its root objects (``contents``) and where it is stored (``path``)."""

    def __init__(self, contents: Iterable[Any] = (), path: Optional[str] = None):
        self.path = path
        self.contents = _Contents(self)
        self.contents.extend(contents)
        self.warnings: List[str] = []

    def all_contents(self) -> list:
        """Every object of the resource, depth first."""
        out: list = []
        for root in self.contents:
            out.append(root)
            out.extend(root.e_all_contents())
        return out

    def save(self, path: Optional[str] = None) -> None:
        path = path or self.path
        if path is None:
            raise ValueError("no path to save to")
        with open(path, "w", encoding="utf-8") as f:
            f.write(dumps(self))
        self.path = path

    def __repr__(self) -> str:
        return f"Resource({self.path!r}, {len(self.contents)} roots)"


def uri_fragment(obj: Any) -> str:
    """EMF's URI fragment of an object: ``//@books.0``, or ``/1/@books.0`` in a document with
    several roots."""
    segments: list = []
    cur = obj
    while cur._e_container is not None:
        feature = cur._e_containing_feature
        container = cur._e_container
        if feature.many:
            segments.append(f"@{feature.name}.{feature.__get__(container).index(cur)}")
        else:
            segments.append(f"@{feature.name}")
        cur = container
    segments.reverse()
    resource = cur._e_resource
    root = "" if resource is None or len(resource.contents) <= 1 else str(resource.contents._items.index(cur))
    return "/" + root + ("/" + "/".join(segments) if segments else "")


def _id_of(obj: Any) -> Optional[str]:
    for f in type(obj)._e_features:
        if f.id and not f.many:
            value = f.__get__(obj)
            if value is not None:
                return _format_value(f, value)
    return None


def _format_value(feature: Feature, value: Any) -> str:
    if feature.kind == "boolean":
        return "true" if value else "false"
    if feature.kind == "enum":
        return value.literal
    if feature.kind == "real":
        return _format_real(value)
    return str(value)


def _parse_value(feature: Feature, text: str) -> Any:
    kind = feature.kind
    if kind == "boolean":
        if text.strip() not in ("true", "false"):
            raise ValueError(f"{text!r} is not a boolean")
        return text.strip() == "true"
    if kind == "integer":
        return int(text.strip())
    if kind == "real":
        return float(text.strip())
    if kind == "enum":
        return feature.type.from_literal(text)
    return text


def loads(text: str, path: Optional[str] = None) -> Resource:
    """Loads an XMI document from a string. Problems that do not prevent loading (unknown
    features, unresolved references) are collected in the resource's ``warnings``."""
    namespaces: dict = {}
    import io

    events = ET.iterparse(io.StringIO(text), events=("start-ns", "start"))
    root_element = None
    for event, item in events:
        if event == "start-ns":
            prefix, uri = item
            namespaces.setdefault(prefix, uri)
        elif root_element is None:
            root_element = item
    # iterparse built the whole tree; its root is the first start element.
    resource = Resource(path=path)
    loader = _Loader(resource, namespaces)
    if root_element is None:
        raise ValueError("empty document")
    if root_element.tag == f"{{{XMI_NS}}}XMI":
        for child in root_element:
            resource.contents.append(loader.root(child))
    else:
        resource.contents.append(loader.root(root_element))
    loader.resolve()
    return resource


def load(path: str) -> Resource:
    """Loads an XMI file."""
    with open(path, encoding="utf-8") as f:
        return loads(f.read(), path)


class _Loader:
    def __init__(self, resource: Resource, namespaces: dict):
        self.resource = resource
        self.namespaces = namespaces
        self.ids: dict = {}
        self.pending: list = []

    def warn(self, message: str) -> None:
        self.resource.warnings.append(message)

    def class_named(self, qname: str) -> Any:
        prefix, _, name = qname.rpartition(":")
        uri = self.namespaces.get(prefix, "")
        package = _packages.get(uri)
        if package is None or name not in package.classifiers:
            raise ValueError(f"unknown class {qname!r}")
        return package.classifiers[name]

    def root(self, element: ET.Element) -> Any:
        xsi_type = element.get(f"{{{XSI_NS}}}type")
        if xsi_type is not None:
            cls = self.class_named(xsi_type)
        else:
            uri, _, name = element.tag[1:].partition("}") if element.tag.startswith("{") else ("", "", element.tag)
            package = _packages.get(uri)
            if package is None or name not in package.classifiers:
                raise ValueError(f"unknown class {element.tag!r}")
            cls = package.classifiers[name]
        return self.object(element, cls)

    def object(self, element: ET.Element, cls: Any) -> Any:
        if not isinstance(cls, type) or not issubclass(cls, EObject) or cls._e_abstract:
            raise ValueError(f"cannot instantiate {getattr(cls, '_e_name', cls)!r}")
        obj = cls()
        xmi_id = element.get(f"{{{XMI_NS}}}id")
        if xmi_id is not None:
            self.ids[xmi_id] = obj
        for key, value in element.attrib.items():
            if key.startswith("{"):
                continue
            feature = cls._e_feature(key)
            if feature is None:
                self.warn(f"{cls._e_name} has no feature {key!r}")
            elif feature.is_reference:
                self.pending.append((obj, feature, value.split()))
            else:
                self.set_attribute(obj, feature, value)
        for child in element:
            tag = child.tag.rpartition("}")[2]
            feature = cls._e_feature(tag)
            if feature is None:
                self.warn(f"{cls._e_name} has no feature {tag!r}")
            elif not feature.is_reference:
                self.set_attribute(obj, feature, child.text or "")
            elif child.get("href") is not None:
                self.warn(f"references to other documents are not supported: {child.get('href')!r}")
            elif feature.containment:
                xsi_type = child.get(f"{{{XSI_NS}}}type")
                child_cls = self.class_named(xsi_type) if xsi_type else feature.type
                _add_to(obj, feature, self.object(child, child_cls))
            else:
                self.warn(f"unexpected element {tag!r} for a non-containment reference")
        for f in cls._e_features:
            if f.id and not f.many:
                value = f.__get__(obj)
                if value is not None:
                    self.ids.setdefault(_format_value(f, value), obj)
        return obj

    def set_attribute(self, obj: Any, feature: Feature, text: str) -> None:
        try:
            value = _parse_value(feature, text)
        except ValueError as e:
            self.warn(f"{type(obj)._e_name}.{feature.name}: {e}")
            return
        if feature.many:
            feature.__get__(obj).append(value)
        else:
            obj._e_values[feature.name] = value

    def resolve(self) -> None:
        for obj, feature, refs in self.pending:
            for ref in refs:
                target = self.find(ref)
                if target is None:
                    self.warn(f"cannot resolve {ref!r} ({type(obj)._e_name}.{feature.name})")
                    continue
                if not isinstance(target, feature.type):
                    self.warn(f"{ref!r} is not a {feature.type._e_name} ({type(obj)._e_name}.{feature.name})")
                    continue
                if feature.many:
                    feature.__get__(obj).append(target)
                elif feature.container:
                    continue
                else:
                    feature.__set__(obj, target)

    def find(self, ref: str) -> Any:
        ref = ref.split("#", 1)[1] if "#" in ref else ref
        if ref in self.ids:
            return self.ids[ref]
        if not ref.startswith("/"):
            return None
        segments = ref.split("/")[1:]
        roots = self.resource.contents._items
        head = segments.pop(0) if segments else ""
        try:
            cur = roots[int(head) if head else 0]
        except (ValueError, IndexError):
            return None
        for segment in segments:
            if not segment:
                continue
            if not segment.startswith("@"):
                return None
            name, _, index = segment[1:].partition(".")
            feature = type(cur)._e_feature(name)
            if feature is None:
                return None
            value = feature.__get__(cur)
            try:
                cur = value[int(index)] if feature.many else value
            except (ValueError, IndexError):
                return None
            if cur is None:
                return None
        return cur


def _escape(text: str) -> str:
    return (text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")
            .replace("\n", "&#xA;").replace("\r", "&#xD;").replace("\t", "&#x9;"))


def dumps(resource: Any) -> str:
    """The XMI document of a resource (or of one root object, or a list of root objects)."""
    if isinstance(resource, EObject):
        roots = [resource]
    elif isinstance(resource, Resource):
        roots = list(resource.contents)
    else:
        roots = list(resource)
    prefixes: dict = {}

    def note(cls: Any) -> str:
        package = cls._e_package
        prefix = package.ns_prefix or package.name
        prefixes.setdefault(prefix, package.ns_uri)
        return f"{prefix}:{cls._e_name}"

    def ref(target: Any) -> str:
        return _id_of(target) or uri_fragment(target)

    lines: list = []
    xsi_used = [False]

    def write(obj: Any, tag: str, declared: Any, depth: int, root: bool) -> None:
        cls = type(obj)
        attrs: list = []
        if not root and cls is not declared:
            attrs.append(f'xsi:type="{note(cls)}"')
            xsi_used[0] = True
        children: list = []
        for f in cls._e_features:
            if not f.serialized or not f.is_set(obj):
                continue
            value = f.__get__(obj)
            if not f.is_reference:
                if f.many:
                    children.extend(("text", f.name, _format_value(f, v)) for v in value)
                else:
                    attrs.append(f'{f.name}="{_escape(_format_value(f, value))}"')
            elif f.containment:
                for v in (value if f.many else [value]):
                    children.append(("object", f, v))
            elif not f.container:
                targets = list(value) if f.many else [value]
                attrs.append(f'{f.name}="{_escape(" ".join(ref(t) for t in targets))}"')
        indent = "  " * depth
        head = f"{indent}<{tag}"
        if root:
            head += "{ROOTATTRS}"
        head += "".join(f" {a}" for a in attrs)
        if not children:
            lines.append(head + "/>")
            return
        lines.append(head + ">")
        for child in children:
            if child[0] == "text":
                lines.append(f"{indent}  <{child[1]}>{_escape(child[2])}</{child[1]}>")
            else:
                write(child[2], child[1].name, child[1].type, depth + 1, False)
        lines.append(f"{indent}</{tag}>")

    single = len(roots) == 1
    for r in roots:
        tag = note(type(r))
        write(r, tag, None, 0 if single else 1, single)
    namespaces = f' xmi:version="2.0" xmlns:xmi="{XMI_NS}" xmlns:xsi="{XSI_NS}"'
    namespaces += "".join(f' xmlns:{p}="{_escape(u)}"' for p, u in sorted(prefixes.items()))
    if single:
        lines[0] = lines[0].replace("{ROOTATTRS}", namespaces, 1)
        body = lines
    else:
        body = [f"<xmi:XMI{namespaces}>", *lines, "</xmi:XMI>"]
    return '<?xml version="1.0" encoding="UTF-8"?>\n' + "\n".join(body) + "\n"


def save(resource: Any, path: str) -> None:
    """Writes a resource (or root objects) as an XMI file."""
    with open(path, "w", encoding="utf-8") as f:
        f.write(dumps(resource))


# ---------------------------------------------------------------------------- validation


class Diagnostic:
    """A problem found by ``validate``: a violated (or failing) invariant or multiplicity."""

    def __init__(self, obj: Any, constraint: str, kind: str, status: str, message: Optional[str] = None):
        self.object = obj
        #: ``Class::Name`` of the invariant, or ``Class::feature`` for multiplicities.
        self.constraint = constraint
        #: ``"invariant"`` or ``"multiplicity"``.
        self.kind = kind
        #: ``"violated"``, or ``"error"`` when the invariant could not be evaluated.
        self.status = status
        self.message = message

    def __str__(self) -> str:
        what = "violated" if self.status == "violated" else "failed"
        detail = f": {self.message}" if self.message else ""
        return f"{self.constraint} {what} on {label(self.object)}{detail}"

    def __repr__(self) -> str:
        return f"Diagnostic({self})"


def _objects(target: Any) -> list:
    if isinstance(target, Resource):
        return target.all_contents()
    if isinstance(target, EObject):
        return [target, *target.e_all_contents()]
    out: list = []
    for t in target:
        out.extend(_objects(t))
    return out


def validate(target: Any, *, multiplicities: bool = True) -> List[Diagnostic]:
    """Checks the invariants (and, with ``multiplicities``, the bounds of the features) of
    an object and everything it contains, of a resource, or of a list of them."""
    out: List[Diagnostic] = []
    for obj in _objects(target):
        cls = type(obj)
        if multiplicities:
            for f in cls._e_features:
                if f.container:
                    continue
                value = f.__get__(obj)
                count = len(value) if f.many else (0 if value is None else 1)
                if count < f.lower:
                    out.append(Diagnostic(obj, f"{cls._e_name}::{f.name}", "multiplicity", "violated",
                                          f"{f.name} needs at least {f.lower} value(s), has {count}"))
                elif f.many and f.upper >= 0 and count > f.upper:
                    out.append(Diagnostic(obj, f"{cls._e_name}::{f.name}", "multiplicity", "violated",
                                          f"{f.name} allows at most {f.upper} value(s), has {count}"))
        seen: set = set()
        for klass in cls.__mro__:
            for qualified, check, message in vars(klass).get("_e_invariants", ()):
                if qualified in seen:
                    continue
                seen.add(qualified)
                try:
                    value = getattr(obj, check)()
                except Exception as e:  # noqa: BLE001 - any failure makes the invariant invalid
                    out.append(Diagnostic(obj, qualified, "invariant", "error",
                                          f"evaluated to invalid: {e or type(e).__name__}"))
                    continue
                if value is True:
                    continue
                if value is False:
                    text = None
                    if message is not None:
                        try:
                            text = to_string(getattr(obj, message)())
                        except Exception:  # noqa: BLE001
                            text = None
                    out.append(Diagnostic(obj, qualified, "invariant", "violated", text))
                else:
                    out.append(Diagnostic(obj, qualified, "invariant", "error", f"evaluated to {to_string(value)}"))
    return out


# ---------------------------------------------------------------------------- OCL library

UNLIMITED = math.inf


class Tuple:
    """An OCL tuple: parts by name."""

    def __init__(self, **parts: Any):
        self.__dict__.update(parts)

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Tuple) and vars(self) == vars(other)

    def __hash__(self) -> int:
        return hash(tuple(sorted((k, repr(v)) for k, v in vars(self).items())))

    def __repr__(self) -> str:
        return to_string(self)


def _format_real(r: float) -> str:
    if math.isfinite(r) and r == int(r) and abs(r) < 1e16:
        return f"{r:.1f}"
    if math.isinf(r):
        return "inf" if r > 0 else "-inf"
    text = repr(r)
    return text


def _render(value: Any, quote: bool) -> str:
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return "*" if value == UNLIMITED else _format_real(value)
    if isinstance(value, str):
        if not quote:
            return value
        return "'" + value.replace("\\", "\\\\").replace("'", "\\'").replace("\n", "\\n").replace("\t", "\\t") + "'"
    if isinstance(value, Enum):
        return str(value)
    if isinstance(value, EObject):
        return label(value)
    if isinstance(value, Tuple):
        return "Tuple{" + ", ".join(f"{k} = {_render(v, True)}" for k, v in vars(value).items()) + "}"
    if isinstance(value, type):
        return getattr(value, "_e_name", value.__name__)
    if isinstance(value, (list, EList)):
        return "Collection{" + ", ".join(_render(v, True) for v in value) + "}"
    return str(value)


def to_string(value: Any) -> str:
    """OCL's ``toString()``: literal syntax, strings unquoted."""
    return _render(value, False)


def is_undefined(value: Callable[[], Any]) -> bool:
    """``oclIsUndefined()``: the value is null or cannot be evaluated."""
    try:
        return value() is None
    except Exception:  # noqa: BLE001
        return True


def is_invalid(value: Callable[[], Any]) -> bool:
    """``oclIsInvalid()``: evaluating the value fails."""
    try:
        value()
        return False
    except Exception:  # noqa: BLE001
        return True


_PRIMITIVES = {
    "Boolean": lambda v: isinstance(v, bool),
    "Integer": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "Real": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "UnlimitedNatural": lambda v: isinstance(v, int) and not isinstance(v, bool) and v >= 0 or v == UNLIMITED,
    "String": lambda v: isinstance(v, str),
    "OclAny": lambda v: v is not None,
    "OclVoid": lambda v: v is None,
}


def is_kind_of(value: Any, t: Any) -> bool:
    """``oclIsKindOf(t)``: ``t`` is a class, an enumeration or a primitive type's name."""
    if isinstance(t, str):
        return _PRIMITIVES[t](value) if t in _PRIMITIVES else False
    return value is not None and isinstance(value, t)


def is_type_of(value: Any, t: Any) -> bool:
    """``oclIsTypeOf(t)``."""
    if isinstance(t, str):
        if t == "Real":
            return isinstance(value, float)
        return _PRIMITIVES[t](value) if t in _PRIMITIVES else False
    return type(value) is t


def as_type(value: Any, t: Any) -> Any:
    """``oclAsType(t)``: the value if it conforms to ``t`` (null stays null)."""
    if value is None:
        return None
    if t == "Real" and isinstance(value, int) and not isinstance(value, bool):
        return float(value)
    if not is_kind_of(value, t):
        name = t if isinstance(t, str) else getattr(t, "_e_name", t.__name__)
        raise OclInvalid(f"cannot cast {to_string(value)} to {name}")
    return value


def as_set(value: Any) -> list:
    """``oclAsSet()``: a set of the value (empty for null)."""
    return [] if value is None else [value]


def all_instances(context: Any, cls: Any) -> list:
    """``T.allInstances()``: the instances of ``cls`` in the resource of ``context`` (or among
    the objects contained by its root, when it is not in a resource)."""
    root = context
    while root._e_container is not None:
        root = root._e_container
    objects = root._e_resource.all_contents() if root._e_resource is not None else [root, *root.e_all_contents()]
    return [o for o in objects if isinstance(o, cls)]


def safe_get(source: Any, attr: str) -> Any:
    """``source?.attr``."""
    return None if source is None else getattr(source, attr)


def safe_call(source: Any, method: str, *args: Any) -> Any:
    """``source?.method(args)``."""
    return None if source is None else getattr(source, method)(*args)


def require(value: Any, what: str) -> Any:
    if value is None:
        raise OclInvalid(f"{what} is null")
    return value


# numbers

def number_max(a: Any, b: Any) -> Any:
    r = a if a >= b else b
    return float(r) if isinstance(a, float) or isinstance(b, float) else r


def number_min(a: Any, b: Any) -> Any:
    r = a if a <= b else b
    return float(r) if isinstance(a, float) or isinstance(b, float) else r


def div(a: int, b: int) -> int:
    if b == 0:
        raise OclInvalid("division by zero")
    q = abs(a) // abs(b)
    return q if (a >= 0) == (b >= 0) else -q


def mod(a: int, b: int) -> int:
    if b == 0:
        raise OclInvalid("division by zero")
    return a - div(a, b) * b


def divide(a: Any, b: Any) -> float:
    if b == 0:
        raise OclInvalid("division by zero")
    return a / b


def floor(x: Any) -> int:
    return math.floor(x)


def round_(x: Any) -> int:
    return math.floor(x + 0.5)


def to_integer(x: Any) -> int:
    if isinstance(x, str):
        try:
            return int(x.strip())
        except ValueError:
            raise OclInvalid(f"'{x}' is not an integer") from None
    return int(x)


def to_real(x: Any) -> float:
    if isinstance(x, str):
        try:
            return float(x.strip())
        except ValueError:
            raise OclInvalid(f"'{x}' is not a number") from None
    return float(x)


# strings (positions are 1-based)

def substring(s: str, lower: int, upper: int) -> str:
    if lower < 1 or upper < lower - 1 or upper > len(s):
        raise OclInvalid(f"substring({lower}, {upper}) out of range for a string of size {len(s)}")
    return s[lower - 1:upper]


def to_boolean(s: str) -> bool:
    t = s.strip()
    if t not in ("true", "false"):
        raise OclInvalid(f"'{s}' is not a Boolean")
    return t == "true"


def index_of(s: str, sub: str) -> int:
    return s.find(sub) + 1


def last_index_of(s: str, sub: str) -> int:
    return s.rfind(sub) + 1


def string_at(s: str, i: int) -> str:
    if i < 1 or i > len(s):
        raise OclInvalid(f"index {i} out of range")
    return s[i - 1]


def _java_replacement(replacement: str) -> str:
    # Java's `$1` group references become Python's `\g<1>`.
    out = re.sub(r"\\(.)", lambda m: m.group(1).replace("\\", "\\\\"), replacement)
    return re.sub(r"\$(\d+)", r"\\g<\1>", out)


def matches(s: str, regex: str) -> bool:
    try:
        return re.fullmatch(regex, s) is not None
    except re.error as e:
        raise OclInvalid(f"invalid regular expression: {e}") from None


def replace_all(s: str, regex: str, replacement: str) -> str:
    try:
        return re.sub(regex, _java_replacement(replacement), s)
    except re.error as e:
        raise OclInvalid(f"invalid regular expression: {e}") from None


def replace_first(s: str, regex: str, replacement: str) -> str:
    try:
        return re.sub(regex, _java_replacement(replacement), s, count=1)
    except re.error as e:
        raise OclInvalid(f"invalid regular expression: {e}") from None


def tokenize(s: str, delimiters: str = " \t\n\r\f", keep: bool = False) -> list:
    out: list = []
    cur = ""
    for c in s:
        if c in delimiters:
            if cur:
                out.append(cur)
                cur = ""
            if keep:
                out.append(c)
        else:
            cur += c
    if cur:
        out.append(cur)
    return out


# collections (lists; the kind is known statically and passed where it matters)

def unique(items: Iterable[Any]) -> list:
    """The items without duplicates, first occurrences kept."""
    out: list = []
    for i in items:
        if i not in out:
            out.append(i)
    return out


def at(items: Any, i: int) -> Any:
    if i < 1 or i > len(items):
        raise OclInvalid(f"index {i} out of range 1..{len(items)}")
    return items[i - 1]


def first(items: Any) -> Any:
    if len(items) == 0:
        raise OclInvalid("first() of an empty collection")
    return items[0]


def last(items: Any) -> Any:
    if len(items) == 0:
        raise OclInvalid("last() of an empty collection")
    return items[-1]


def coll_max(items: Any) -> Any:
    if len(items) == 0:
        raise OclInvalid("max() of an empty collection")
    return max(items)


def coll_min(items: Any) -> Any:
    if len(items) == 0:
        raise OclInvalid("min() of an empty collection")
    return min(items)


def coll_sum(items: Any) -> Any:
    total: Any = 0
    for i in items:
        total = total + require(i, "an element of sum()")
    return total


def index_of_element(items: Any, x: Any) -> int:
    for n, i in enumerate(items):
        if i == x:
            return n + 1
    raise OclInvalid("indexOf(): element not found")


def includes_all(items: Any, other: Any) -> bool:
    return all(o in items for o in other)


def excludes_all(items: Any, other: Any) -> bool:
    return all(o not in items for o in other)


def flatten(items: Any) -> list:
    out: list = []
    for i in items:
        if isinstance(i, (list, EList)):
            out.extend(flatten(i))
        else:
            out.append(i)
    return out


def including(items: Any, x: Any, unique_kind: bool) -> list:
    out = list(items)
    if not unique_kind or x not in out:
        out.append(x)
    return out


def excluding(items: Any, x: Any) -> list:
    return [i for i in items if i != x]


def including_all(items: Any, other: Any, unique_kind: bool) -> list:
    out = list(items)
    for o in other:
        if not unique_kind or o not in out:
            out.append(o)
    return out


def excluding_all(items: Any, other: Any) -> list:
    return [i for i in items if i not in other]


def intersection(items: Any, other: Any, bag: bool) -> list:
    if not bag:
        return unique(i for i in items if i in other)
    remaining = list(other)
    out: list = []
    for i in items:
        if i in remaining:
            remaining.remove(i)
            out.append(i)
    return out


def symmetric_difference(items: Any, other: Any) -> list:
    return unique([i for i in items if i not in other] + [o for o in other if o not in items])


def append(items: Any, x: Any, unique_kind: bool) -> list:
    out = [i for i in items if i != x] if unique_kind else list(items)
    out.append(x)
    return out


def prepend(items: Any, x: Any, unique_kind: bool) -> list:
    out = [i for i in items if i != x] if unique_kind else list(items)
    out.insert(0, x)
    return out


def insert_at(items: Any, index: int, x: Any, unique_kind: bool) -> list:
    out = [i for i in items if i != x] if unique_kind else list(items)
    if index < 1 or index > len(out) + 1:
        raise OclInvalid(f"index {index} out of range")
    out.insert(index - 1, x)
    return out


def sub_sequence(items: Any, lower: int, upper: int) -> list:
    if lower < 1 or upper > len(items) or lower > upper:
        raise OclInvalid("subSequence(): indices out of range")
    return list(items[lower - 1:upper])


def select_by_kind(items: Any, t: Any) -> list:
    return [i for i in items if is_kind_of(i, t)]


def select_by_type(items: Any, t: Any) -> list:
    return [i for i in items if i is not None and is_type_of(i, t)]


def product(items: Any, other: Any) -> list:
    return [Tuple(first=a, second=b) for a in items for b in other]


def difference(items: Any, other: Any) -> list:
    return [i for i in items if i not in other]


def set_equals(a: Any, b: Any) -> bool:
    return all(x in b for x in a) and all(y in a for y in b)


def bag_equals(a: Any, b: Any) -> bool:
    if len(a) != len(b):
        return False
    rest = list(b)
    for x in a:
        if x not in rest:
            return False
        rest.remove(x)
    return True


def collection(items: Iterable[Any], unique_kind: bool) -> list:
    """A collection literal's items (deduplicated for sets)."""
    return unique(items) if unique_kind else list(items)


def ocl_range(lower: int, upper: int) -> list:
    if upper - lower > 10_000_000:
        raise OclInvalid("range is too large")
    return list(range(lower, upper + 1))


# iterators

def one(items: Any, body: Callable[[Any], Any]) -> bool:
    return sum(1 for i in items if body(i) is True) == 1


def is_unique(keys: Iterable[Any]) -> bool:
    seen: list = []
    for k in keys:
        if k in seen:
            return False
        seen.append(k)
    return True


def any_(items: Any, body: Callable[[Any], Any]) -> Any:
    for i in items:
        if body(i):
            return i
    return None


def sorted_by(items: Any, key: Callable[[Any], Any]) -> list:
    try:
        return sorted(items, key=key)
    except TypeError:
        raise OclInvalid("sortedBy: keys are not comparable") from None


def closure(items: Any, body: Callable[[Any], Any]) -> list:
    out: list = []
    queue = list(items)
    while queue:
        item = queue.pop(0)
        value = body(item)
        nexts = list(value) if isinstance(value, (list, EList)) else ([] if value is None else [value])
        for n in nexts:
            if n is not None and n not in out:
                out.append(n)
                queue.append(n)
    return out


def iterate(items: Any, acc: Any, body: Callable[[Any, Any], Any]) -> Any:
    for i in items:
        acc = body(i, acc)
    return acc
